C.taleAdd = list => list.forEach(t => { if (C.TALES[t.id]) return; C.TALES[t.id] = t; C.TALE_LIST.push(t); });
const isFree = g => !!(g && C.CAMPS[g.camp] && C.CAMPS[g.camp].free);
const arr = x => x == null ? [] : [].concat(x);
const done = (g, id) => (g.taleDone || []).includes(id);
const busy = (g, id) => (g.jobs || []).some(j => j.tale === id && ['open', 'done'].includes(j.status));
const trust = (g, s) => (g.chron && g.chron.trust ? g.chron.trust[s] || 0 : 0);
const flag = (g, f) => !!(g.taleFlags || {})[f];
/* открыто ли сказание сейчас */
C.taleOk = function (g, T) {
  if (done(g, T.id) || busy(g, T.id)) return false;
  const lv = Q.lvl(g);
  if (T.lv && (lv < T.lv[0] || lv > T.lv[1] + 6)) return false; // слабым не дают; сильным — ещё долго дают, но плата по их силе
  const N = T.need || {};
  if (N.after && !arr(N.after).every(id => done(g, id))) return false;
  if (N.anyOf && !arr(N.anyOf).some(id => done(g, id))) return false;
  if (N.not && arr(N.not).some(id => done(g, id))) return false;
  if (N.fame != null && (g.fame || 0) < N.fame) return false;
  if (N.side && Object.entries(N.side).some(([s, v]) => (v >= 0 ? trust(g, s) < v : trust(g, s) > v))) return false;
  if (N.season && !arr(N.season).includes(C.seasonOf ? C.seasonOf(g) : 'summer')) return false;
  if (N.cls && !C.alive(g).some(h => arr(N.cls).includes(h.cls))) return false;
  if (N.faith && !C.alive(g).some(h => C.faithOf && arr(N.faith).includes(C.faithOf(h)))) return false;
  if (N.flag && !arr(N.flag).every(f => flag(g, f))) return false;
  if (N.noFlag && arr(N.noFlag).some(f => flag(g, f))) return false;
  if (N.day && (g.day || 1) < N.day) return false;
  return true;
};
/* на месте видно не больше двух сказаний: сперва продолжения начатых цепочек, остальные сменяются раз в седмицу */
const hshA = s => { let h = 0; for (const ch of String(s)) h = (h * 31 + ch.charCodeAt(0)) >>> 0; return h; };
