  if (lore) { g.taleLore = (g.taleLore || []).concat({id: T.id, title: Q.title(j), land: T.land, t: lore, day: g.day}); C.note(g, lore); }
  if (T.gift && R.item(T.gift)) { const h = C.recipient(g); if (h) { h.inv.push(T.gift); j.taleGift = T.gift; } }
  if (T.side && C.trust && g.chron) Object.entries(T.side).forEach(([s, v]) => C.trust(g, s, v));
