  if (T && j && !j.repText) { const end = j.taleEnd && T.ends && T.ends[j.taleEnd]; j.repText = [T.repIntro || `${Q.giverName(j)} ждёт вас на пороге.`, arr((end && end.win) || T.win || 'Спасибо вам.').join(' ')]; }
