FREE.scenes.w2_factions = function (g) {
  const vis = C.facVisible(g), knownYou = vis.filter(id => C.facStep(g, id) !== 0), none = vis.filter(id => C.facStep(g, id) === 0);
  const lines = [['n', 'Корчмарь вытирает руки о передник и подсаживается к вам. «Про вас-то? Как не говорить, говорят. Кто добром, кто худом — слушайте сами».']];
  if (!knownYou.length) lines.push(['n', 'Пока о вас нигде толком не слыхали: ни купцы, ни дознаватели, ни лесные. Сделайте что-нибудь заметное — и заговорят.']);
  knownYou.forEach(id => lines.push(['n', `${C.FACTIONS[id].name}: ${C.facPhrase(g, id)}.`]));
  if (knownYou.length && none.length) lines.push(['n', `Остальные о вас пока не слыхали: ${none.map(id => C.FACTIONS[id].name).join(', ')}.`]);
  const ch = vis.map(id => ({t: `Расспросить: ${C.FACTIONS[id].name}`, do: g2 => { g2.w2facSel = id; return 'w2_faction'; }}));
  ch.push({t: 'Назад', do: g2 => { g2.w2facSel = null; return backOf(g2); }});
  return {title: 'Что о вас говорят', bg: 'hut', art: 'tavern', lines, choices: ch};
};
FREE.scenes.w2_faction = function (g) {
  const id = g.w2facSel, F = C.FACTIONS[id];
  if (!F || !C.facKnown(g, id)) return {title: 'Что о вас говорят', bg: 'hut', art: 'tavern', lines: [['n', 'Корчмарь пожимает плечами: о таких здесь не говорят.']], choices: [{t: 'Назад', go: 'w2_factions'}]};
  const s = C.facStep(g, id), lines = [['n', F.short], ['n', F.about]];
  lines.push(['n', `Где их искать: ${placeNames(F)}. Кого знают: ${F.faces}. Они ${sideRu[F.side] || 'сами по себе'}.`]);
  const en = facNames(g, F.enemies, F), fr = facNames(g, F.friends, F);
  if (en || fr) lines.push(['n', `${fr ? 'В ладу с ними: ' + fr + '. ' : ''}${en ? 'Не терпят: ' + en + '.' : ''}`]);
  lines.push(['n', `Что о вас: ${C.facPhrase(g, id)}.`]);
  const pk = C.facPerks(g, id), th = C.facThreats(g, id);
  if (pk.length) lines.push(['n', 'Что это вам даёт: ' + pk.map(b => b.t).join('; ') + '.']);
  const next = F.benefits.filter(b => b.s > s).sort((a, b) => a.s - b.s)[0];
  if (next && s >= 0) lines.push(['n', `Если станете им ближе: ${next.t}.`]);
  if (th.length) lines.push(['n', 'Чем грозит: ' + th.map(b => b.t).join('; ') + '.']);
  if (has(g, id, 'secret')) F.secret.slice(0, s >= 3 ? 2 : 1).forEach((t, k) => { lines.push(['n', 'Шёпотом: ' + t]); tellSecret(g, id, k); });
  const open = C.facJobsOpen(g, id);
  if (open.length) lines.push(['n', 'Их люди ищут помощи: ' + [...new Set(open.map(T => (nodes()[arr(T.at)[0]] || {}).name))].join(', ') + '.']);
  else if (s < 0) lines.push(['n', 'Своих дел вам они сейчас не доверят.']);
  return {title: F.name, bg: 'hut', art: 'tavern', lines, choices: [{t: 'О других', go: 'w2_factions'}, {t: 'Назад', do: g2 => { g2.w2facSel = null; return backOf(g2); }}]};
};

