  const F = S(g), x = data || {}, h = leadHero(g), reg = x.reg || curReg(g), n = nodes()[g.loc];
  const v = Object.assign({}, KIND(k).v); Object.entries(x.side || {}).forEach(([s, d]) => { v[s] = (v[s] || 0) + (d > 0 ? 2 : d < 0 ? -2 : 0); });
  const d = {id: 'd' + (g.w2deeds.length + 1) + '_' + g.day + '_' + (hsh(k + (x.what || '') + g.time) % 997), k, day: g.day, reg,
    what: x.what || '', place: x.place || (n ? n.name : ''), boss: x.boss || '', n: Math.max(1, x.n || C.alive(g).length + (g.mercs || []).length || 1),
    who: x.who || (h ? h.name : 'отряд'), sex: x.sex || (h ? h.sex : 'm'), wsex: x.wsex || null, party: C.alive(g).map(y => y.name).slice(0, 5), psex: C.alive(g).map(y => y.sex === 'f' ? 'f' : 'm').slice(0, 5), v, end: x.end || null};
  if (KIND(k).black || v.folk < 0) d.black = 1;
  g.w2deeds.push(d); if (g.w2deeds.length > 60) g.w2deeds.shift();
  let L = KIND(k).list || 0; if (x.side && x.side.kap > 0) L += 1; if (x.side && x.side.oko > 0) L -= 1; if (x.list) L += x.list;
  if (L) C.fameListAdd(g, L);
