const arr = x => x == null ? [] : [].concat(x);
const isFree = g => !!g && g.camp === 'free';
const cap = s => s ? s[0].toUpperCase() + s.slice(1) : s;
const hsh = s => { let h = 2166136261; for (const ch of String(s)) h = Math.imul(h ^ ch.charCodeAt(0), 16777619); return h >>> 0; };
const roll = (g, key) => (hsh((g.seed || g.camp) + '|lb|' + key) % 1000) / 1000;

C.LOREBITS = C.LOREBITS || {}; C.LOREBIT_LIST = C.LOREBIT_LIST || [];
C.LORESETS = C.LORESETS || {}; C.LORESET_LIST = C.LORESET_LIST || [];
