  if (T) ch.push({t: `Выслушать, о чём ${he(p)} просит`, tale: T.id, do: g2 => { const T2 = C.TALES[T.id]; if (!T2 || !C.taleOk(g2, T2)) return 'w2_ppl'; const j = C.taleJob(g2, T2); g2.jobPending = j; g2.jobOffer = j.id; g2.jobFrom = 'town'; return 'q_offer'; }});
