/* регистрация: люди и их сказания */
C.pplAdd = function (list) {
  const tales = [];
  arr(list).forEach(p => {
    if (!p || !p.id || C.W2_PPL[p.id]) return;
    C.W2_PPL[p.id] = p; C.W2_PEOPLE.push(p);
    const lv = LAND_LV[p.land] || [1, 3], at = C.pplNodes(p); let prev = null;
    (p.tales || []).forEach((T, i) => {
      T.id = T.id || `w2p_${p.id}_${i + 1}`; T.land = p.land; T.at = T.at || (at.length > 1 ? at : at[0]);
      T.who = {n: p.n, t: p.t, sex: p.sex, ppl: p.ppl};
      if (!T.lv) T.lv = i === 0 ? [lv[0], Math.min(lv[1], lv[0] + 2)] : i === 1 ? [lv[0] + 1, lv[1]] : [Math.min(lv[1], lv[0] + 2), lv[1] + 1];
      if (i > 0 && prev) T.need = Object.assign({}, T.need || {}, {after: (T.need && T.need.after) || prev});
      T.diff = T.diff || 'mid'; if (T.pay == null) T.pay = 1; if (T.dl == null) T.dl = 10;
      if (!T.fac && p.fac && C.FACTIONS && C.FACTIONS[p.fac]) T.fac = {[p.fac]: i === p.tales.length - 1 ? 2 : 1};
      T.w2ppl = p.id; prev = T.id; tales.push(T);
    });
  });
  C.taleAdd(tales);
};
C.pplAdd(PPL);
G.C = C;
