  if (s === 'con') { const dm = R.mod(h.stats.con) - m0; if (dm) { const k = dm * Math.max(1, h.level || 1); h.hpMax = Math.max(4, (h.hpMax || 4) + k); h.hp = Math.max(1, Math.min(h.hpMax, (h.hp || 1) + k)); } }
  const p1 = R.powerMax ? R.powerMax(h) : 0; if (p1 !== p0) h.power = Math.max(0, Math.min(p1, (h.power || 0) + p1 - p0));
